      $id=gint($_GET,'id',1,2147483647);$j=studio_job($id);echo '<p><a class="btn outline" href="'.esc(admin_url('deliveries',['job_id'=>$id])).'">Website deliveries →</a></p>';?><section class="workspace-card"><form method="post"><?php admin_action('studio_job');studio_hidden('id',$id);studio_hidden('client_id',$j['client_id']);admin_input('title','Project title',$j['title']);admin_select('stage','Stage',studio_stages(),$j['stage']);admin_textarea('summary','Summary',$j['summary']);admin_textarea('milestones','Milestones',$j['milestones']);?><button class="btn gold">Save project</button></form><?php $stageEvents=all('SELECT * FROM '.table('studio_stage_events').' WHERE job_id=? ORDER BY id DESC LIMIT 20',[$id]);if($stageEvents):?><h3>Stage history</h3><?php foreach($stageEvents as $e):?><p class="stage-event" id="stage-<?=(int)$e['id']?>"><small><?=esc($e['created_at'])?> UTC</small> · <?=esc(studio_stages()[$e['from_stage']]??$e['from_stage'])?> → <strong><?=esc(studio_stages()[$e['to_stage']]??$e['to_stage'])?></strong></p><?php endforeach;?><?php endif;?></section><div class="workspace-grid"><section class="workspace-card"><h2>Publish a design or proposal version</h2><p>Published versions are immutable. To revise, publish a new version; pending older versions cannot be approved.</p><form method="post"><?php admin_action('studio_publish');studio_hidden('job_id',$id);admin_select('kind','Review type',['design'=>'Design','proposal'=>'Proposal'],'design');admin_input('title','Version title','','text','required');admin_textarea('body','Design details / proposal scope','',8,30000);admin_input('preview_url','HTTPS preview link (optional)','','url');?><button class="btn gold">Publish new version</button></form><?php foreach(all('SELECT v.*,b.file_id AS preview_file FROM '.table('studio_versions').' v LEFT JOIN '.table('studio_version_files').' b ON b.version_id=v.id WHERE v.job_id=? ORDER BY v.id DESC',[$id]) as $v):?><div class="workspace-version" id="review-<?=(int)$v['id']?>"><strong><?=esc($v['kind'].' v'.$v['version_no'].' · '.$v['title'])?></strong><p><?=esc($v['decision'].' · '.$v['feedback'])?></p><?php if($v['preview_file']):?><p><a class="btn outline" href="<?=esc(admin_url('studio-job',['id'=>$id,'preview'=>(int)$v['id']]))?>" target="_blank" rel="noopener noreferrer">Open protected preview ↗</a></p><?php else:?><form method="post" enctype="multipart/form-data"><?php admin_action('studio_preview');studio_hidden('job_id',$id);studio_hidden('version_id',$v['id']);?><label>Protected preview — PDF, PNG or JPEG, up to 8 MB<input name="document" type="file" required accept=".pdf,.png,.jpg,.jpeg"></label><button class="btn outline">Attach preview</button></form><?php endif;?></div><?php endforeach;?></section><section class="workspace-card"><h2>Conversation</h2><?php foreach(all((contacts_ready()?'SELECT m.*,ct.name AS contact_name FROM '.table('studio_messages').' m LEFT JOIN '.table('studio_contacts').' ct ON m.author_type=\'contact\' AND ct.id=m.author_id WHERE m.job_id=? AND m.author_type<>\'internal\' ORDER BY (m.id=?) DESC,m.id DESC LIMIT 100':'SELECT * FROM '.table('studio_messages').' WHERE job_id=? AND author_type<>\'internal\' ORDER BY (id=?) DESC,id DESC LIMIT 100'),[$id,(int)($_GET['focus_message']??0)]) as $m)echo '<div class="workspace-message" id="message-'.(int)$m['id'].'"><small>'.esc(($m['author_type']==='contact'?($m['contact_name']??'contact').' (contact)':$m['author_type']).' · '.$m['created_at']).' UTC</small>'.esc($m['body']).'</div>';?><form method="post"><?php admin_action('studio_message');studio_hidden('job_id',$id);admin_textarea('body','Message');?><button class="btn gold">Save message to workspace</button></form><h3>Private files</h3><?php foreach(all('SELECT * FROM '.table('studio_files').' WHERE job_id=?',[$id]) as $f)echo '<p id="file-'.esc($f['id']).'"><a href="'.esc(admin_url('studio-job',['id'=>$id,'file'=>$f['id']])).'">'.esc($f['original_name']).' ↓</a></p>';?><form method="post" enctype="multipart/form-data"><?php admin_action('studio_upload');studio_hidden('job_id',$id);?><label>PDF, PNG or JPEG, up to 8 MB<input name="document" type="file" required accept=".pdf,.png,.jpg,.jpeg"></label><button class="btn outline">Upload privately</button></form><h3>Staff-only notes</h3><p class="hint">Internal notes are never shown to the client or its contacts.</p><?php foreach(all('SELECT m.*,u.name AS staff_name FROM '.table('studio_messages').' m LEFT JOIN '.table('users').' u ON u.id=m.author_id WHERE m.job_id=? AND m.author_type=\'internal\' ORDER BY m.id DESC LIMIT 100',[$id]) as $n)echo '<div class="workspace-message" id="note-'.(int)$n['id'].'"><small>'.esc(($n['staff_name']??'Staff').' · staff only · '.$n['created_at']).' UTC</small>'.esc($n['body']).'</div>';?><form method="post"><?php admin_action('studio_note');studio_hidden('job_id',$id);admin_textarea('body','Staff-only note');?><button class="btn outline">Save internal note</button></form></section></div><section class="workspace-card"><h2>Milestone tracking</h2><?php if(!studio_milestones_ready()):?><p class="hint">Run the workspace database update under Version &amp; database to enable dated milestone tracking.</p><?php else:?><p class="hint">Structured milestones with states and optional target dates; the client and permitted contacts see this list. The narrative milestones field above remains for free-form notes.</p><?php foreach(studio_milestones($id) as $ms):?><div class="workspace-version" id="milestone-<?=(int)$ms['id']?>"><form method="post"><?php admin_action('studio_milestone');studio_hidden('job_id',$id);studio_hidden('id',$ms['id']);admin_input('title','Milestone',$ms['title']);admin_select('state','State',studio_milestone_states(),$ms['state']);admin_input('target_date','Target date (YYYY-MM-DD, optional)',$ms['target_date']);?><button class="btn outline">Save milestone</button></form></div><?php endforeach;?><form method="post"><?php admin_action('studio_milestone');studio_hidden('job_id',$id);studio_hidden('id','0');admin_input('title','New milestone','','text','required');admin_select('state','State',studio_milestone_states(),'pending');admin_input('target_date','Target date (YYYY-MM-DD, optional)','');?><button class="btn gold">Add milestone</button></form><?php endif;?></section><section class="workspace-card"><h2>Manual invoices</h2><?php catalog_project_entry($id);if(payments_ready()&&staff_can('payments.manage'))echo '<p><a href="'.esc(admin_url('payments')).'">Prepare an invoice payment request</a></p>';?><p>No card charging or recurring billing is enabled. Mark paid only after independently verifying payment.</p><form method="post"><?php admin_action('studio_invoice');studio_hidden('job_id',$id);admin_input('title','Invoice title');admin_input('amount','Amount in USD (for example 125.00)');admin_textarea('instructions','Payment instructions');?><button class="btn gold">Issue invoice</button></form><?php foreach(all('SELECT * FROM '.table('studio_invoices').' WHERE job_id=? ORDER BY id DESC',[$id]) as $inv):?><div class="workspace-version"><h3><?=esc($inv['reference'].' · '.$inv['title'])?></h3><p>$<?=gmoney((int)$inv['amount_cents'])?> USD · <?=esc($inv['status'])?></p><?php catalog_invoice_view($inv);catalog_void_form($inv);if(ledger_ready()&&staff_can('payments.manage'))echo '<p><a href="'.esc(admin_url('invoice-payments',['invoice_id'=>$inv['id']])).'">Review balance and payment history</a></p>';if(!ledger_ready()&&$inv['status']==='issued'&&(!catalog_snapshot((int)$inv['id'])||staff_can('catalog.manage'))):?><form method="post"><?php admin_action('studio_paid');studio_hidden('job_id',$id);studio_hidden('invoice_id',$inv['id']);admin_input('paid_note','Verified payment reference');admin_check('confirm','I independently verified that payment was received.',false);?><button class="btn outline">Record received payment</button></form><?php endif;?></div><?php endforeach;?></section><?php
